 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # A full-width row marks the color of a bar; extend the matching
    # left-aligned half-width bar using color 1 for its missing half.
    full = next((row[0] for row in grid if all(v == row[0] for v in row)), None)
    if full is None:
        return out
    for r, row in enumerate(grid):
        if all(v == full for v in row[:w // 2]) and all(v != full for v in row[w // 2:]):
            out[r][w // 2:] = [1] * (w - w // 2)
    return out
